style.css:
@-moz-document domain("manhuaus.com") {
/* Меняем главный фон и фон страниц на черный */
    body, html, .site-content, .c-page-content, .main-col, .body-open {
        background-color: #000000 !important;
        background: #000000 !important;
    }

    /* Перекрашиваем текстовые блоки и контейнеры */
    .c-blog-post, .entry-content, .item-summary, .post-title h1, h2, h3, p {
        color: #e0e0e0 !important;
    }

    /* Корректируем фон в режиме чтения глав */
    .read-container, .cha-page, .reading-content {
        background-color: #000000 !important;
    }
}
